-- V3__payouts_expand.sql (subgoal: add the new column without blocking anyone for long)
SET LOCAL lock_timeout = '5s';
ALTER TABLE payouts ADD COLUMN amount_minor bigint;

// subgoal: copy old to new in small, restartable batches
fun backfill(conn: Connection, batch: Int = 5_000) {
    var total = 0
    while (true) {
        val n = Migration.backfillBatch(conn, batch)   // UPDATE ... WHERE id IN (... LIMIT ?)
        if (n == 0) break
        total += n
        log.info("backfilled $total payouts")
        Thread.sleep(50)                               // leave room for live traffic and replication
    }
}

-- V5__payouts_switch_writes.sql (subgoal: old column optional, new one required for new rows)
SET LOCAL lock_timeout = '5s';
ALTER TABLE payouts ALTER COLUMN amount DROP NOT NULL;
ALTER TABLE payouts ADD CONSTRAINT payouts_amount_minor_not_null NOT NULL amount_minor NOT VALID;

-- V6__payouts_validate.sql (subgoal: check old rows under a lock that allows reads and writes)
ALTER TABLE payouts VALIDATE CONSTRAINT payouts_amount_minor_not_null;

-- V7__payouts_contract.sql (subgoal: remove the old shape once nothing can use it)
SET LOCAL lock_timeout = '5s';
ALTER TABLE payouts DROP COLUMN amount;
